//! Native B0D1A0/B0D140 target selection, B27CD0 ID and B27280 flag writes.
//! These cached flags do not implement physical DSP or device output.
use std::collections::BTreeMap;
use crate::audio_bus_parameter_notification as notification;
pub const FLAG_OFFSETS:[usize;5]=[0x480,0x494,0x4a8,0x4bc,0x4c0];
#[derive(Debug,Clone)] pub struct Voice{pub raw:[u8;0x500]}
impl Voice{fn bus(&self)->u32{u32::from_le_bytes(self.raw[0x4d0..0x4d4].try_into().unwrap())}}
#[derive(Debug,Clone)] pub struct Root{pub voice:u32,pub key:[u32;2]}
#[derive(Debug,Default)] pub struct Store{pub voices:BTreeMap<u32,Voice>,pub bus_ids:BTreeMap<u32,u32>,pub registered:Vec<u32>,pub roots:Vec<Root>}
#[derive(Debug,PartialEq,Eq)] pub enum Error{MissingVoice(u32),MissingBus(u32)}
#[derive(Debug,Clone,serde::Serialize)] pub struct Call{pub voice:u32,pub args:[u32;2]}
impl Store{
 fn apply(&mut self,voice:u32,value:u32,mask:u32)->Result<Call,Error>{let target=self.voices.get_mut(&voice).ok_or(Error::MissingVoice(voice))?;for (bit,offset)in FLAG_OFFSETS.iter().enumerate(){if mask&(1<<bit)!=0{target.raw[*offset]=(target.raw[*offset]&!1)|((value>>bit)as u8&1);}}Ok(Call{voice,args:[value,mask]})}
 pub fn root(&mut self,value:u32,mask:u32)->Result<Vec<Call>,Error>{let Some(root)=self.roots.iter().find(|r|r.key==[0,0]) else{return Ok(vec![]);};let voice=root.voice;Ok(vec![self.apply(voice,value,mask)?])}
 pub fn bus(&mut self,id:u32,value:u32,mask:u32)->Result<Vec<Call>,Error>{let mut selected=Vec::new();for &reference in &self.registered{let voice=self.voices.get(&reference).ok_or(Error::MissingVoice(reference))?;let bus=voice.bus();let found=if bus==0{0}else{*self.bus_ids.get(&bus).ok_or(Error::MissingBus(bus))?};if found==id{selected.push(reference);}}selected.into_iter().map(|r|self.apply(r,value,mask)).collect()}
}
/// Bind actual registered targets to qualified Bus notification dispatch.
/// RTPC evaluation must be supplied by ManagerBackend; no value fallback.
pub struct Backend<'a>{pub store:&'a mut Store,pub calls:Vec<Call>}
impl notification::Backend for Backend<'_>{
 fn rtpc(&mut self,_:u32,_:u32,_:u32)->Result<f32,notification::Error>{Err(notification::Error::Backend("RTPC manager dependency required"))}
 fn root(&mut self,v:u32,m:u32)->Result<(),notification::Error>{let calls=self.store.root(v,m).map_err(notification::Error::Application)?;self.calls.extend(calls);Ok(())}
 fn bus(&mut self,id:u32,v:u32,m:u32)->Result<(),notification::Error>{let calls=self.store.bus(id,v,m).map_err(notification::Error::Application)?;self.calls.extend(calls);Ok(())}
}
#[cfg(test)] mod tests{
 use super::*;
 fn manager(row:&serde_json::Value,subscriber:u32)->crate::audio_rtpc_manager::Manager{use crate::audio_rtpc_manager::{Manager,Record};let mut m=Manager::default();if row["found"]==true{m.bindings.insert((subscriber,row["parameter"].as_u64().unwrap() as u32),serde_json::from_value(row["curves"].clone()).unwrap());}for r in row["records"].as_array().unwrap(){m.records.insert(r["rtpc"].as_u64().unwrap() as u32,Record{default:r["default"].as_f64().unwrap() as f32,overrides:r["overrides"].as_array().unwrap().iter().map(|v|(v["owner"].as_u64().unwrap() as u32,v["value"].as_f64().unwrap() as f32)).collect()});}m}
 #[test] fn audio_bus_target_selection_and_flag_writes_match1728_native_cases(){let p:serde_json::Value=serde_json::from_str(&crate::audio_test_fixture("data/4.20/audio_bus_control_application_contract.json")).unwrap();assert_eq!(p["case_count"],1728);for(case,row)in p["cases"].as_array().unwrap().iter().enumerate(){let refs=[0x30001000,0x30002000,0x30003000];let mut store=Store::default();store.bus_ids=BTreeMap::from([(0x30004000,1234),(0x30004100,1234)]);store.registered=refs.to_vec();let profile=row["profile"].as_u64().unwrap() as usize;for(i,&r)in refs.iter().enumerate(){store.voices.insert(r,Voice{raw:crate::audio_spatial_controls::tests::hex(row["before"][i].as_str().unwrap())});store.roots.push(Root{voice:r,key:[if i==profile{0}else{i as u32+1},0]});}let value=row["value"].as_u64().unwrap() as u32;let mask=row["mask"].as_u64().unwrap() as u32;let calls=if row["operation"]=="root"{store.root(value,mask)}else{store.bus(row["id"].as_u64().unwrap() as u32,value,mask)}.unwrap();assert_eq!(serde_json::json!(calls),row["calls"],"selected targets {case}");for(i,&r)in refs.iter().enumerate(){assert_eq!(store.voices[&r].raw,crate::audio_spatial_controls::tests::hex::<0x500>(row["after"][i].as_str().unwrap()),"complete target {case}/{i}");}}}
 #[test] fn audio_whole_bus_notification_manager_and_targets_match5760_native_cases(){use crate::audio_bus_registry::Bus;let p:serde_json::Value=serde_json::from_str(&crate::audio_test_fixture("data/4.20/audio_bus_notification_application_contract.json")).unwrap();assert_eq!(p["case_count"],5760);for(case,row)in p["cases"].as_array().unwrap().iter().enumerate(){let bus=Bus{reference:0x30001000,raw:crate::audio_spatial_controls::tests::hex(row["before"].as_str().unwrap())};let mut inputs=notification::Store::default();if row["cache_present"]==true{inputs.caches.insert(0x30002000,notification::Cache{effect_ids:[if row["nonempty"]==true{1}else{0};4],flags:row["cached_flags"].as_u64().unwrap() as u8});}if row["source_present"]==true{inputs.source_flags.insert(0x30003000,row["source_flags"].as_u64().unwrap() as u8);}let manager=manager(row,bus.reference);let refs=[0x30005000,0x30006000,0x30007000];let mut store=Store::default();store.bus_ids.insert(bus.reference,bus.word(8));store.registered=refs.to_vec();let seed=row["target_seed"].as_u64().unwrap() as u8;let free=row["root_first_free"].as_u64().unwrap() as usize;let mut before=Vec::new();for(i,&r)in refs.iter().enumerate(){let mut raw=[seed;0x500];raw[0x4d0..0x4d4].copy_from_slice(&(if i<2{bus.reference}else{0}).to_le_bytes());before.push(raw);store.voices.insert(r,Voice{raw});store.roots.push(Root{voice:r,key:[if i==free{0}else{i as u32+1},0]});}let mut targets=Backend{store:&mut store,calls:vec![]};let mut backend=notification::ManagerBackend{manager:&manager,dependencies:&mut targets,curves:vec![]};let calls=inputs.notify(&bus,row["parameter"].as_u64().unwrap() as u32,&mut backend).unwrap();let curves=std::mem::take(&mut backend.curves);drop(backend);let applied=std::mem::take(&mut targets.calls);drop(targets);let mut trace=Vec::new();for c in &calls{trace.push(serde_json::json!(c));match c{notification::Call::Rtpc{..}=>trace.extend(curves.iter().map(|v|serde_json::json!({"kind":"curve","index":v.curve,"input_bits":v.input_bits}))),_=>trace.extend(applied.iter().map(|v|serde_json::json!({"kind":"apply","voice":v.voice,"args":v.args})))}}assert_eq!(serde_json::json!(trace),row["calls"],"whole call order {case}");assert_eq!(bus.raw,crate::audio_spatial_controls::tests::hex::<200>(row["after"].as_str().unwrap()),"bus {case}");for(i,&r)in refs.iter().enumerate(){let mut expected=before[i];for(j,&offset)in FLAG_OFFSETS.iter().enumerate(){expected[offset]=row["after_target_flags"][i][j].as_u64().unwrap() as u8;}assert_eq!(store.voices[&r].raw,expected,"complete target preserves unrelated bytes {case}/{i}");}}}
 #[test] fn audio_bus_application_missing_references_do_not_mutate_earlier_targets(){let mut store=Store::default();let mut raw=[0xa5;0x500];raw[0x4d0..0x4d4].copy_from_slice(&2u32.to_le_bytes());store.voices.insert(1,Voice{raw});store.bus_ids.insert(2,123);store.registered=vec![1,3];assert!(matches!(store.bus(123,0,31),Err(Error::MissingVoice(3))));assert_eq!(store.voices[&1].raw,raw);store.roots=vec![Root{voice:3,key:[1,0]},Root{voice:1,key:[0,0]}];assert_eq!(store.root(0,1).unwrap().len(),1);}
}
